SELECT rating_bucket, unique_citys, max_rating FROM (SELECT CASE WHEN rating >= 4.0 THEN 'high' WHEN rating >= 1.8 THEN 'mid' ELSE 'low' END AS rating_bucket, COUNT(DISTINCT rating) AS unique_citys, MAX(rating) AS max_rating FROM suppliers GROUP BY CASE WHEN rating >= 4.0 THEN 'high' WHEN rating >= 1.8 THEN 'mid' ELSE 'low' END) AS x WHERE unique_citys > 9 ORDER BY unique_citys DESC, max_rating DESC
